// Obtener datos directamente del webhook
const body = $node.Webhook16.json.body;

console.log('📥 DATOS DEL WEBHOOK RECIBIDOS:', JSON.stringify(body, null, 2));

let residente_nombre = 'Desconocido';
let residente_edad = 'Desconocida';
let residente_diagnosticos = 'Sin diagnósticos';
let residente_medicamentos = 'Sin medicamentos';
let residente_estado_cognitivo = 'No especificado';
let signosTexto = '';

// Extraer de ficha_residente (enviada desde React)
if (body.ficha_residente) {
  const ficha = body.ficha_residente;
  console.log('✅ Ficha residente encontrada:', ficha.nombre_completo);

  residente_nombre = ficha.nombre_completo || 'Desconocido';
  residente_diagnosticos = ficha.diagnosticos_actuales || 'Sin diagnósticos';
  residente_medicamentos = ficha.medicamentos_actuales || 'Sin medicamentos';
  residente_estado_cognitivo = ficha.estado_cognitivo || 'No especificado';

  // Calcular edad
  if (ficha.fecha_nacimiento) {
    const fechaNac = new Date(ficha.fecha_nacimiento);
    const hoy = new Date();
    if (!isNaN(fechaNac)) {
      residente_edad = hoy.getFullYear() - fechaNac.getFullYear();
      const mes = hoy.getMonth() - fechaNac.getMonth();
      if (mes < 0 || (mes === 0 && hoy.getDate() < fechaNac.getDate())) {
        residente_edad--;
      }
    }
  }
} else {
  console.error('❌ No se encontró ficha_residente en el body');
}

// Extraer signos vitales (enviados desde React)
if (body.signos_vitales && Array.isArray(body.signos_vitales) && body.signos_vitales.length > 0) {
  console.log('✅ Signos vitales encontrados:', body.signos_vitales.length, 'registros');

  signosTexto = body.signos_vitales.map((s, index) => {
    const fecha = s.fecha_registro ? new Date(s.fecha_registro).toLocaleString('es-ES') : 'Sin fecha';
    const temp = s.temperatura || 'N/A';
    const paSist = s.presion_sistolica || 'N/A';
    const paDiast = s.presion_diastolica || 'N/A';
    const fc = s.frecuencia_cardiaca || 'N/A';
    const sat = s.saturacion_oxigeno || 'N/A';
    const obs = s.observaciones || 'Ninguna';

    return `Registro ${index + 1} [${fecha}]:\n  - Temperatura: ${temp}°C\n  - Presión Arterial: ${paSist}/${paDiast} mmHg\n  - Frecuencia Cardíaca: ${fc} lpm\n  - Saturación O2: ${sat}%\n  - Observaciones: ${obs}`;
  }).join('\n\n');

  console.log('📊 Signos vitales formateados correctamente');
} else {
  console.warn('⚠️ No hay registros de signos vitales o el array está vacío');
  signosTexto = 'No hay registros recientes de signos vitales disponibles para análisis.';
}

console.log('✅ Datos preparados para IA');
console.log('📋 Residente:', residente_nombre);
console.log('📋 Edad:', residente_edad);
console.log('📋 Signos vitales length:', signosTexto.length);

// Extraer el último signo vital para acceso rápido
let ultimoSigno = {};
if (body.signos_vitales && Array.isArray(body.signos_vitales) && body.signos_vitales.length > 0) {
  ultimoSigno = body.signos_vitales[0];
}

return {
  residente_nombre,
  residente_edad,
  residente_diagnosticos,
  residente_medicamentos,
  residente_estado_cognitivo,
  signos_vitales_historial: signosTexto,
  id_residente: body.id_residente,
  ficha_residente: body.ficha_residente,
  signos_vitales: body.signos_vitales || [],
  ultimo_signo_vital: ultimoSigno,
  cantidad_signos: (body.signos_vitales && Array.isArray(body.signos_vitales)) ? body.signos_vitales.length : 0
};

