// 1. Obtener la respuesta cruda que viene del nodo Gemini
const item = $input.first();
const jsonInput = item.json;

let rawText = '';

// --- LÓGICA DE EXTRACCIÓN CORREGIDA ---

// CASO 1: Estructura exacta de tu captura de pantalla (content -> parts -> text)
if (jsonInput.content && jsonInput.content.parts && Array.isArray(jsonInput.content.parts) && jsonInput.content.parts.length > 0) {
    rawText = jsonInput.content.parts[0].text;
} 
// CASO 2: Estructura alternativa de Google (response -> parts -> text)
else if (jsonInput.response && jsonInput.response.parts && Array.isArray(jsonInput.response.parts)) {
    rawText = jsonInput.response.parts[0].text;
} 
// CASO 3: Texto directo en 'text' (Salida estándar de LangChain)
else if (jsonInput.text) {
    rawText = jsonInput.text;
} 
// CASO 4: Texto directo en 'output'
else if (jsonInput.output) {
    rawText = jsonInput.output;
}
// FALLBACK: Si algo falla, convertimos lo que sea que haya llegado a texto
else {
    // Si llegamos aquí, tomamos el objeto entero y lo convertimos a string para no romper el flujo
    rawText = JSON.stringify(jsonInput); 
}

// --- BLINDAJE DE SEGURIDAD (Corrección de tu error línea 24) ---
// Aseguramos que rawText sea SIEMPRE un string antes de usar .substring
if (typeof rawText !== 'string') {
    // Si por alguna razón sigue siendo un objeto, lo forzamos a string
    rawText = JSON.stringify(rawText);
}

console.log('📥 Texto crudo recibido:', rawText.substring(0, 100) + '...');

// 2. Limpiar el formato Markdown (Bloques de código ```json ... ```)
const cleanJson = rawText
    .replace(/```json/g, '') // Elimina la apertura ```json
    .replace(/```/g, '')     // Elimina el cierre ```
    .trim();                 // Elimina espacios en blanco

// 3. Parsear el string a Objeto Javascript Real
let parsedData = {};

try {
    parsedData = JSON.parse(cleanJson);
    console.log('✅ JSON parseado correctamente');
} catch (error) {
    console.error('❌ Error parseando JSON:', error.message);
    console.log('Texto que falló:', cleanJson);

    // Estructura de emergencia
    return {
        resumen_general: "Hubo un error técnico procesando la respuesta de la IA.",
        tendencias: {
             presion_arterial: "No disponible",
             frecuencia_cardiaca: "No disponible",
             saturacion_oxigeno: "No disponible",
             temperatura: "No disponible"
        },
        factores_riesgo: [],
        recomendaciones_preventivas: ["Revise los registros técnicos."],
        alertas: [],
        observaciones_generales: "Error de formato."
    };
}

// 4. Asegurar respuesta estructurada (Previene errores en React)
const respuestaSegura = {
    resumen_general: parsedData.resumen_general || "Sin resumen disponible.",
    tendencias: {
        presion_arterial: parsedData.tendencias?.presion_arterial || "Sin datos recientes.",
        frecuencia_cardiaca: parsedData.tendencias?.frecuencia_cardiaca || "Sin datos recientes.",
        saturacion_oxigeno: parsedData.tendencias?.saturacion_oxigeno || "Sin datos recientes.",
        temperatura: parsedData.tendencias?.temperatura || "Sin datos recientes."
    },
    factores_riesgo: Array.isArray(parsedData.factores_riesgo) ? parsedData.factores_riesgo : [],
    recomendaciones_preventivas: Array.isArray(parsedData.recomendaciones_preventivas) ? parsedData.recomendaciones_preventivas : [],
    alertas: Array.isArray(parsedData.alertas) ? parsedData.alertas : [],
    observaciones_generales: parsedData.observaciones_generales || "Continuar monitoreo."
};

return respuestaSegura;

// Obtener el análisis de IA del nodo anterior
const analisisIA = $input.first().json;

// Obtener datos preparados desde el nodo anterior
const datosPreparados = $('Preparar Datos').first().json;
const ficha = datosPreparados.ficha_residente || {};

console.log('📦 Enriqueciendo respuesta final...');
console.log('ID Residente:', datosPreparados.id_residente);
console.log('Nombre:', datosPreparados.residente_nombre);
console.log('Cantidad signos vitales:', datosPreparados.cantidad_signos);

const respuestaFinal = {
  id_residente: datosPreparados.id_residente,
  nombre: datosPreparados.residente_nombre,
  fecha_generacion: new Date().toISOString(),
  residente_info: {
    edad: datosPreparados.residente_edad,
    diagnosticos: datosPreparados.residente_diagnosticos,
    medicamentos: datosPreparados.residente_medicamentos,
    alergias: ficha.alergias || 'No registradas',
    movilidad: ficha.tipo_movilidad || 'No especificada',
    estado_cognitivo: datosPreparados.residente_estado_cognitivo,
    cantidad_registros_analizados: datosPreparados.cantidad_signos || 0
  },
  analisis_ia: analisisIA,
  estado: "exitoso",
  metadata: {
    fecha_consulta: new Date().toISOString(),
    version_analisis: '3.0',
    modelo_ia: 'Gemini 2.5 Pro'
  }
};

console.log('✅ RESPUESTA FINAL COMPLETA GENERADA');
console.log('Estado:', respuestaFinal.estado);
console.log('Longitud resumen:', respuestaFinal.analisis_ia.resumen_general?.length || 0);
console.log('Factores riesgo:', respuestaFinal.analisis_ia.factores_riesgo?.length || 0);

return respuestaFinal;

