return items.map(item => {
  const data = item.json || {};
  if (!data.residente_id) {
    return { json: { error: 'Residente no encontrado o sin registros.', estado_alerta: 'Pendiente', descripcion: 'Sin registros recientes.', estado_clase: 'status-neutral' } };
  }
  return {
    json: {
      residente_id: data.residente_id,
      nombre_completo: data.nombre_completo,
      estado_alerta: data.estado_alerta,
      descripcion: data.descripcion_estado,
      estado_clase: data.estado_clase,
      ultima_actualizacion: data.ultima_actualizacion
    }
  };
});

return items.map(item => {
  const message = item.json.message || {};
  const text = ((message.text || '') + ' ' + (message.caption || '')).trim();
  const chatId = message.chat && message.chat.id ? String(message.chat.id) : null;
  const staticData = this.getWorkflowStaticData('global');
  const match = text.match(/portal_familiar(?:[\s_:\-]+)(\d{1,10})/i);
  let selectedId = null;
  if (match && match[1]) {
    selectedId = match[1].trim();
    if (chatId) {
      const storeKey = 'resident:' + chatId;
      staticData[storeKey] = selectedId;
    }
  } else if (chatId) {
    const storeKey = 'resident:' + chatId;
    selectedId = staticData[storeKey] || null;
  }
  item.json.selectedResidentId = selectedId;
  return item;
});

return items.map(item => {
  const residentsResponse = item.json.residentSnapshot || {};
  const vitalsResponse = item.json.vitalsSnapshot || {};
  const fichaResponse = item.json.residentsFicha || {};

  const datasetRaw = Array.isArray(residentsResponse.data)
    ? residentsResponse.data
    : (Array.isArray(residentsResponse.residentes)
      ? residentsResponse.residentes
      : (Array.isArray(residentsResponse)
        ? residentsResponse
        : []));

  const vitalsRaw = Array.isArray(vitalsResponse.data)
    ? vitalsResponse.data
    : (Array.isArray(vitalsResponse.registros)
      ? vitalsResponse.registros
      : (Array.isArray(vitalsResponse)
        ? vitalsResponse
        : []));

  const fichaRaw = Array.isArray(fichaResponse.data)
    ? fichaResponse.data
    : (Array.isArray(fichaResponse.residentes)
      ? fichaResponse.residentes
      : (Array.isArray(fichaResponse)
        ? fichaResponse
        : []));

  const normalizeId = (entity, fallback = '') => {
    if (!entity || typeof entity !== 'object') return fallback;
    const candidate = entity.id || entity.residente_id || entity.id_residente || entity.residenteId || entity._id || entity.usuario_id;
    return (candidate !== undefined && candidate !== null) ? String(candidate) : fallback;
  };

  const targetResidentId = item.json.selectedResidentId ? String(item.json.selectedResidentId) : null;
  const filterByTarget = (collection) => {
    if (!targetResidentId) return collection;
    return collection.filter(entry => normalizeId(entry) === targetResidentId);
  };

  const dataset = filterByTarget(datasetRaw);
  const vitals = filterByTarget(vitalsRaw);
  const ficha = filterByTarget(fichaRaw);

  const nameIndex = {};
  dataset.forEach((resident, idx) => {
    const id = normalizeId(resident, `tmp-${idx + 1}`);
    nameIndex[id] = resident.nombre_completo || resident.nombre || resident.alias || `Residente ${idx + 1}`;
  });

  const vitalsByResident = {};
  vitals.forEach((registro) => {
    const residenteId = normalizeId(registro);
    if (!residenteId) return;
    const fecha = registro.fecha_registro || registro.fecha || registro.created_at || null;
    const timestamp = fecha ? new Date(fecha).getTime() : 0;
    const existing = vitalsByResident[residenteId];
    if (!existing || timestamp > existing.timestamp) {
      vitalsByResident[residenteId] = {
        timestamp,
        fechaLabel: fecha ? new Date(fecha).toLocaleString('es-CL', { dateStyle: 'short', timeStyle: 'short' }) : 'Sin fecha',
        sistolica: registro.presion_sistolica || registro.presionSistolica || registro.sistolica || '-',
        diastolica: registro.presion_diastolica || registro.presionDiastolica || registro.diastolica || '-',
        temperatura: registro.temperatura ?? registro.temp ?? '-',
        frecuencia: registro.frecuencia_cardiaca ?? registro.frecuencia ?? '-',
        saturacion: registro.saturacion_oxigeno ?? registro.satO2 ?? '-',
      };
    }
  });

  const fichaByResident = {};
  ficha.forEach((fichaItem, idx) => {
    const id = normalizeId(fichaItem, `ficha-${idx}`);
    if (!id) return;
    fichaByResident[id] = fichaItem;
  });

  const formatVitals = (residentId) => {
    const vital = vitalsByResident[residentId];
    if (!vital) return 'Signos vitales: sin registro reciente.';
    return `Signos vitales (${vital.fechaLabel}): TA ${vital.sistolica}/${vital.diastolica} | Temp ${vital.temperatura}°C | FC ${vital.frecuencia} lpm | SpO2 ${vital.saturacion}%`;
  };

  const formatFicha = (residentId, fallback = {}) => {
    const fichaData = fichaByResident[residentId] || fallback;
    const datos = [];
    const diagnosticos = fichaData.diagnosticos_actuales || fichaData.diagnosticos || null;
    const medicamentos = fichaData.medicamentos_actuales || fichaData.medicamentos || null;
    const dieta = fichaData.tipo_dieta || fichaData.dieta || null;
    const movilidad = fichaData.tipo_movilidad || null;
    if (diagnosticos) datos.push(`Dx: ${diagnosticos}`);
    if (medicamentos) datos.push(`Meds: ${medicamentos}`);
    if (dieta) datos.push(`Dieta: ${dieta}`);
    if (movilidad) datos.push(`Movilidad: ${movilidad}`);
    return datos.length ? `Ficha: ${datos.join(' | ')}` : 'Ficha: sin datos adicionales.';
  };

  const residentSummary = dataset.slice(0, 40).map((resident, index) => {
    const residentId = normalizeId(resident, `tmp-${index + 1}`);
    const nombre = resident.nombre_completo || resident.nombre || `Residente ${index + 1}`;
    const rut = resident.rut || 'RUT no informado';
    const habitacion = resident.habitacion_numero || resident.habitacion || 'Sin habitación';
    const estado = resident.estado || resident.estado_salud || 'Estado no registrado';
    const contacto = resident.contacto_emergencia_nombre
      ? `${resident.contacto_emergencia_nombre} (${resident.contacto_emergencia_telefono || 'sin teléfono'})`
      : 'Contacto de emergencia no registrado';
    return `• ${nombre} | RUT: ${rut} | Hab: ${habitacion} | Estado: ${estado} | ${contacto}
  ${formatVitals(residentId)}
  ${formatFicha(residentId, resident)}`;
  }).join('\n\n');

  const vitalsDigest = vitals.slice(0, 20).map((registro, index) => {
    const residentId = normalizeId(registro, `sv-${index + 1}`);
    const nombre = registro.nombre_residente || nameIndex[residentId] || `Residente ${index + 1}`;
    const fecha = registro.fecha_registro || registro.fecha || registro.created_at || null;
    const fechaLabel = fecha ? new Date(fecha).toLocaleString('es-CL', { dateStyle: 'short', timeStyle: 'short' }) : 'Sin fecha';
    const sistolica = registro.presion_sistolica || registro.sistolica || '-';
    const diastolica = registro.presion_diastolica || registro.diastolica || '-';
    const temperatura = registro.temperatura ?? registro.temp ?? '-';
    const frecuencia = registro.frecuencia_cardiaca ?? registro.frecuencia ?? '-';
    const saturacion = registro.saturacion_oxigeno ?? registro.satO2 ?? '-';
    return `• ${nombre} (${fechaLabel}) -> TA ${sistolica}/${diastolica}, Temp ${temperatura}°C, FC ${frecuencia} lpm, SpO2 ${saturacion}%`;
  }).join('\n');

  const fichaDigest = ficha.slice(0, 20).map((fichaItem, index) => {
    const residentId = normalizeId(fichaItem, `ficha-${index + 1}`);
    const nombre = fichaItem.nombre_completo || nameIndex[residentId] || `Residente ${index + 1}`;
    const diagnosticos = fichaItem.diagnosticos_actuales || fichaItem.diagnosticos || 'Sin diagnósticos registrados';
    const medicamentos = fichaItem.medicamentos_actuales || fichaItem.medicamentos || 'Sin medicamentos registrados';
    const dieta = fichaItem.tipo_dieta || fichaItem.dieta || 'Sin dieta registrada';
    return `• ${nombre}: Dx ${diagnosticos}; Meds ${medicamentos}; Dieta ${dieta}`;
  }).join('\n');

  item.json.residentContext = residentSummary || 'No hay residentes registrados en este momento.';
  item.json.vitalsDigest = vitalsDigest || 'No hay registros recientes de signos vitales.';
  item.json.fichaDigest = fichaDigest || 'No hay fichas administrativas disponibles.';
  item.json.residentCount = dataset.length;
  item.json.rawResidents = dataset.slice(0, 10);
  return item;
});

